// Resilience helpers for external discovery/provider calls. These only add safety;
// existing routes and behavior remain intact.
const AD_FETCH_TIMEOUT_MS = 7000;
const AD_SEARCH_TIMEOUT_MS = 9000;
const AD_MAX_DISCOVERY_SITES = 8;
const AD_MAX_DRAFTS_PER_RUN = 6;

function isBlockedExternalHost(hostname) {
  const h = String(hostname || '').toLowerCase().replace(/\.$/, '');
  if (!h || h === 'localhost' || h.endsWith('.localhost') || h === 'metadata.google.internal') return true;
  if (h === '127.0.0.1' || h === '0.0.0.0' || h === '::1' || h === '[::1]') return true;
  if (/^10\./.test(h) || /^192\.168\./.test(h) || /^169\.254\./.test(h) || /^172\.(1[6-9]|2\d|3[0-1])\./.test(h)) return true;
  if (/^\[?f[cd][0-9a-f]*:/i.test(h)) return true;
  return false;
}

function safeHttpUrl(value) {
  try {
    const u = new URL(String(value || ''));
    if (!/^https?:$/i.test(u.protocol) || isBlockedExternalHost(u.hostname)) return null;
    return u.toString();
  } catch { return null; }
}

async function fetchWithRetry(url, options = {}, attempts = 2, timeoutMs = AD_FETCH_TIMEOUT_MS) {
  let current = safeHttpUrl(url);
  if (!current) throw new Error('external URL blocked or invalid');
  let last;
  for (let i = 0; i < Math.max(1, attempts); i++) {
    try {
      let r;
      for (let hop = 0; hop < 3; hop++) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeoutMs);
        try {
          r = await fetch(current, { ...options, signal: controller.signal, redirect: 'manual' });
        } finally { clearTimeout(timer); }
        if (![301,302,303,307,308].includes(r.status)) break;
        const location = r.headers.get('location');
        const next = safeHttpUrl(location ? new URL(location, current).toString() : '');
        if (!next) throw new Error('external redirect blocked');
        current = next;
      }
      if (r.ok || ![408,425,429,500,502,503,504].includes(r.status) || i === attempts - 1) return r;
      last = new Error(`HTTP ${r.status}`);
    } catch (e) {
      last = e;
      if (i === attempts - 1) throw e;
    }
    await new Promise(resolve => setTimeout(resolve, 250 * (i + 1)));
  }
  throw last || new Error('external request failed');
}

function extractSearchLinks(html, limit = 12, providerHost = "") {
  const out = [], seen = new Set();
  const source = String(html || "");

  function addLink(rawHref) {
    let href = rawHref || "";

    try {
      if (href.startsWith("/url?q=")) {
        href = decodeURIComponent(href.slice(7).split("&")[0]);
      } else if (href.startsWith("/url?")) {
        const u = new URL(href, "https://www.google.com");
        href = u.searchParams.get("q") || u.searchParams.get("url") || "";
      } else if (href.startsWith("//")) {
        href = "https:" + href;
      }

      href = href
  .replace(/&amp;/g, "&")
  .replace(/&#38;/g, "&")
  .replace(/&#x26;/gi, "&");

const parsed = new URL(href, "https://www.bing.com");

if (/bing\.com$/i.test(parsed.hostname) && /^\/ck\/a/i.test(parsed.pathname)) {
  const encoded = parsed.searchParams.get("u") || "";
        if (encoded) {
          let value = decodeURIComponent(encoded);
          if (value.startsWith("a1")) value = value.slice(2);

          try {
            const normalized = value
              .replace(/-/g, "+")
              .replace(/_/g, "/");

            const padded =
              normalized +
              "=".repeat((4 - normalized.length % 4) % 4);

            const decoded = atob(padded);

            if (/^https?:\/\//i.test(decoded)) {
              href = decoded;
            }
          } catch {}
        }
      }

      const safe = safeHttpUrl(href);
      if (!safe) return;

      const u = new URL(safe);

      if (
        /google\./i.test(u.hostname) ||
        /youtube\./i.test(u.hostname) ||
        /bing\./i.test(u.hostname) ||
        /microsoft\.com$/i.test(u.hostname)
      ) return;

      const key = u.origin;

      if (seen.has(key)) return;

      seen.add(key);
      out.push(safe);
    } catch {}
  }

  if (/bing\.com$/i.test(String(providerHost || ""))) {
    const bingRe =
      /<li\b[^>]*class\s*=\s*["'][^"']*\bb_algo\b[^"']*["'][^>]*>[\s\S]*?<h2\b[^>]*>\s*<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>/gi;

    let m;

    while ((m = bingRe.exec(source)) && out.length < limit) {
      addLink(m[1]);
    }
    
  }

  const re =
    /<a\b[^>]*\bhref\s*=\s*["']([^"']+)["'][^>]*>/gi;

  let m;

  while ((m = re.exec(source)) && out.length < limit) {
    addLink(m[1]);
  }

  return out;
}
async function discoverWebLinks(query, limit = 8) {
  const providers = [
    `https://www.google.com/search?q=${encodeURIComponent(query)}&num=12`,
    `https://www.bing.com/search?q=${encodeURIComponent(query)}&count=12`
  ];
  const diagnostics = [];
  const merged = [];
  const seen = new Set();

  for (const searchUrl of providers) {
    const host = new URL(searchUrl).hostname;

    try {
      const r = await fetchWithRetry(
        searchUrl,
        { headers: { "User-Agent": "Mozilla/5.0 (compatible; HAMZEHI-SOCIAL-AI/1.0)" } },
        2,
        AD_SEARCH_TIMEOUT_MS
      );

      if (!r.ok) {
        diagnostics.push({
          provider: host,
          status: r.status,
          ok: false,
          html_length: 0,
          extracted_links: 0
        });
        continue;
      }

      const html = await r.text();
      const links = extractSearchLinks(html, limit, host);

      let added = 0;

      for (const link of links) {
        try {
          const u = new URL(link);
          const key = u.origin;

          if (seen.has(key)) continue;

          seen.add(key);
          merged.push(link);
          added++;

          if (merged.length >= limit) break;
        } catch {}
      }

      diagnostics.push({
        provider: host,
        status: r.status,
        ok: true,
        html_length: html.length,
        extracted_links: links.length,
        added_links: added
      });
    } catch (e) {
      diagnostics.push({
        provider: host,
        status: null,
        ok: false,
        html_length: 0,
        extracted_links: 0,
        added_links: 0,
        error: String(e?.message || e).slice(0, 180)
      });
    }
  }
  return {
    links: merged.slice(0, limit),
    provider: diagnostics.filter(x => x.ok && x.added_links > 0).map(x => x.provider),
    diagnostics
  };
}
