// ---- Owner review of import items → existing authorities ----
async function applyOwnerKnowledgeItem(env,item){
  if(item.item_type==="price_row"){
    // Approving a no-price row records that the configuration has NO authoritative price: nothing is priced or activated.
    if(item.price_minor==null)return {result_ref:"no_authoritative_price:recorded"};
    if(!["IRAN","ARAB"].includes(item.market))throw Error("Select IRAN or ARAB for a price");
    if(item.currency!==MARKET_CURRENCY[item.market])throw Error(`${item.market} prices must be in ${MARKET_CURRENCY[item.market]}`);
    if(!Number.isSafeInteger(item.price_minor)||item.price_minor<=0||!item.product_key)throw Error("A valid product and price are required");
    const active=await env.DB.prepare("SELECT * FROM commercial_price_items WHERE market=? AND product_key=? AND active=1 ORDER BY version DESC LIMIT 1").bind(item.market,item.product_key).first();
    if(active&&active.unit_price_minor===item.price_minor&&active.currency===item.currency)return {result_ref:`commercial_price_items:${active.id}:unchanged`};
    const created=await createPriceItemVersion(env,{market:item.market,base_id:active?.id||undefined,product_key:item.product_key,product_name:[item.product_name,item.size,item.configuration].filter(Boolean).join(" · "),currency:item.currency,unit_price_minor:item.price_minor},"admin");
    return {result_ref:`commercial_price_items:${created.id}:v${created.version}`};
  }
  if(item.item_type==="product_fact"||item.item_type==="rule"){
    await ensureSalesKnowledgeStore(env);
    let value=null;try{value=JSON.parse(item.fact_value_json);}catch{}
    const member=knowledgeFieldType(item.fact_domain,item.fact_attribute)==="member";
    const requestId=("owner-import-"+item.id).replace(/[^A-Za-z0-9_-]/g,"-").slice(0,80);
    const proposal=await proposeSalesKnowledge(env,{id:requestId,operation:member?"EXPAND":"ADD",domain:item.fact_domain,entity_type:item.item_type==="rule"?"business":"model",entity_key:item.item_type==="rule"?"global":item.product_name,attribute:item.fact_attribute,market:item.market==="GLOBAL"?"GLOBAL":item.market,value},{sourceType:"owner_import",parserSource:"owner_import",parserConfidence:1});
    if(proposal.status==="conflict"){const reasons=(()=>{try{return JSON.parse(proposal.conflict_json).map(x=>x.reason)}catch{return []}})();if(reasons.every(r=>r==="duplicate"||r==="duplicate_member"))return {result_ref:`sales_knowledge:already_active`};return {result_ref:`sales_knowledge_change_requests:${proposal.id}:conflict`,conflict:true};}
    // Resume safety: the deterministic request id returns the SAME proposal on retry; never review/apply it twice.
    if(proposal.status==="applied")return {result_ref:`sales_knowledge_facts:${proposal.result_fact_id}`};
    const reviewed=proposal.status==="approved"?proposal:await reviewSalesKnowledge(env,{id:proposal.id,decision:"approve",proposal_hash:proposal.proposal_hash,confirm_sensitive:true,note:"Approved from owner knowledge import review"});
    const applied=await applySalesKnowledge(env,{id:reviewed.id,proposal_hash:reviewed.proposal_hash,confirm_apply:true});
    return {result_ref:`sales_knowledge_facts:${applied.result_fact_id}`};
  }
  if(item.item_type==="visual"){
    const image=await env.DB.prepare("SELECT * FROM owner_product_images WHERE id=? LIMIT 1").bind(item.image_id||"").first();
    if(!image?.visual_media_id)throw Error("Owner image is not available as a visual candidate");
    const attributes=[{type:"model",value:item.product_name},...(item.size?[{type:"size",value:item.size}]:[]),...(item.configuration?[{type:"other",value:item.configuration}]:[]),...(item.category?[{type:"category",value:item.category}]:[])];
    const current=(await env.DB.prepare("SELECT attribute_type,version FROM visual_product_media_attributes WHERE visual_media_id=? AND status='active'").bind(image.visual_media_id).all()).results||[];
    await updateVisualProductAttributes(env,{visual_media_id:image.visual_media_id,attributes:attributes.map(a=>({...a,expected_version:current.find(c=>c.attribute_type===a.type)?.version}))});
    const media=await env.DB.prepare("SELECT version FROM visual_product_media WHERE id=? LIMIT 1").bind(image.visual_media_id).first();
    const verified=await transitionVisualProductMedia(env,{id:image.visual_media_id,action:"verify",expected_version:media.version});
    return {result_ref:`visual_product_media:${verified.id}:verified`};
  }
  throw Error("This item has no structured knowledge to approve; correct or reject it");
}
const OWNER_ITEM_CORRECTABLE=["product_name","size","configuration","category","price_minor","currency","market","fact_value"];
async function reviewOwnerKnowledgeItem(env,body){
  if(!(await ownerImportStoreReady(env)))throw Error("Owner knowledge import requires migration G");
  const id=String(body?.id||""),action=String(body?.action||""),version=Number(body?.expected_version);
  if(!id||!["approve","reject","correct"].includes(action)||!Number.isSafeInteger(version))throw Error("id, expected_version and a valid action are required");
  const item=await env.DB.prepare("SELECT * FROM owner_knowledge_import_items WHERE id=? LIMIT 1").bind(id).first();
  if(!item)throw Error("Import item not found");
  if(item.version!==version)throw Error("Item changed since it was displayed; refresh");
  if(["applied","rejected"].includes(item.review_status))return item;
  const t=now();
  if(action==="reject"){
    if(item.item_type==="visual"){const image=await env.DB.prepare("SELECT visual_media_id FROM owner_product_images WHERE id=?").bind(item.image_id||"").first();const media=image?.visual_media_id?await env.DB.prepare("SELECT version,candidate_status FROM visual_product_media WHERE id=?").bind(image.visual_media_id).first():null;if(media&&media.candidate_status==="candidate")try{await transitionVisualProductMedia(env,{id:image.visual_media_id,action:"reject",expected_version:media.version});}catch{}}
    await env.DB.prepare("UPDATE owner_knowledge_import_items SET review_status='rejected',reviewed_by='admin',reviewed_at=?,version=version+1,updated_at=? WHERE id=? AND version=?").bind(t,t,id,version).run();
    return await env.DB.prepare("SELECT * FROM owner_knowledge_import_items WHERE id=?").bind(id).first();
  }
  if(action==="correct"){
    const c=body?.corrections||{};if(Object.keys(c).some(k=>!OWNER_ITEM_CORRECTABLE.includes(k)))throw Error("Unsupported correction field");
    const next={product_name:item.product_name,size:item.size,configuration:item.configuration,category:item.category,price_minor:item.price_minor,currency:item.currency,market:item.market,fact_value_json:item.fact_value_json};
    for(const k of ["product_name","size","configuration","category"])if(k in c){const v=String(c[k]??"").normalize("NFKC").trim();if(v.length>240)throw Error(k+" is too long");next[k]=v||null;}
    if("size" in c&&next.size){const d=ownerDims(next.size);if(d.size)next.size=d.size;}
    if("price_minor" in c){const v=Number(ownerAscii(c.price_minor).replace(/,/g,""));if(!Number.isSafeInteger(v)||v<=0)throw Error("Price must be a positive whole amount in the market's minor unit");next.price_minor=v;}
    if("currency" in c){if(!["TOMAN","USD"].includes(String(c.currency).toUpperCase()))throw Error("Currency must be TOMAN or USD");next.currency=String(c.currency).toUpperCase();}
    if("market" in c){if(!["IRAN","ARAB","GLOBAL"].includes(String(c.market).toUpperCase()))throw Error("Invalid market");next.market=String(c.market).toUpperCase();}
    if("fact_value" in c){const v=String(c.fact_value??"").normalize("NFKC").trim();if(!v||v.length>2000)throw Error("Fact value is required");next.fact_value_json=JSON.stringify(v);}
    const productOk=item.item_type==="rule"||!!next.product_name,priceOk=item.item_type!=="price_row"||(next.price_minor==null&&next.currency==null)||(Number.isSafeInteger(next.price_minor)&&next.currency===MARKET_CURRENCY[next.market]);
    let history=[];try{history=JSON.parse(item.history_json||"[]");}catch{}
    history.push({at:t,by:"admin",before:{product_name:item.product_name,size:item.size,configuration:item.configuration,category:item.category,price_minor:item.price_minor,currency:item.currency,market:item.market,fact_value_json:item.fact_value_json}});
    // A correction resolves ambiguity only when the corrected item is complete; it never approves anything by itself.
    const r=await env.DB.prepare("UPDATE owner_knowledge_import_items SET product_name=?,size=?,configuration=?,category=?,price_minor=?,currency=?,market=?,fact_value_json=?,product_key=?,parse_status=?,issues_json=?,history_json=?,version=version+1,updated_at=? WHERE id=? AND version=? AND review_status='pending_review'")
      .bind(next.product_name,next.size,next.configuration,next.category,next.price_minor,next.currency,next.market,next.fact_value_json,next.product_name?ownerItemKey(next.product_name,next.size,next.configuration):null,productOk&&priceOk?"parsed":"ambiguous",JSON.stringify(productOk&&priceOk?[{code:"corrected_by_owner"}]:[{code:"still_incomplete"}]),JSON.stringify(history.slice(-20)),t,id,version).run();
    if(!r.meta?.changes)throw Error("Concurrent correction conflict");
    return await env.DB.prepare("SELECT * FROM owner_knowledge_import_items WHERE id=?").bind(id).first();
  }
  if(item.parse_status!=="parsed")throw Error("Ambiguous or rejected entries must be corrected before approval");
  if(item.item_type==="price_row"&&body?.confirm_commercial!==true)throw Error("Explicit commercial confirmation is required for prices");
  const claimed=await env.DB.prepare("UPDATE owner_knowledge_import_items SET review_status='approved',reviewed_by='admin',reviewed_at=?,version=version+1,updated_at=? WHERE id=? AND version=? AND review_status='pending_review'").bind(t,t,id,version).run();
  if(!claimed.meta?.changes)throw Error("Concurrent review conflict");
  try{
    const result=await applyOwnerKnowledgeItem(env,{...item,review_status:"approved"});
    await env.DB.prepare("UPDATE owner_knowledge_import_items SET review_status=?,result_ref=?,applied_at=?,updated_at=? WHERE id=?").bind(result.conflict?"approved":"applied",result.result_ref,result.conflict?null:now(),now(),id).run();
    try{await audit(env,"owner_knowledge_item_applied","Owner approved an imported knowledge item",{item_id:id,item_type:item.item_type,result_ref:result.result_ref});}catch{}
  }catch(error){
    // Keep the owner's decision visible but nothing half-applied: return the item to review with the reason.
    await env.DB.prepare("UPDATE owner_knowledge_import_items SET review_status='pending_review',issues_json=?,version=version+1,updated_at=? WHERE id=?").bind(JSON.stringify([{code:"apply_failed",detail:sanitizeOperationalError(error?.message||error)}]),now(),id).run();
    throw error;
  }
  return await env.DB.prepare("SELECT * FROM owner_knowledge_import_items WHERE id=?").bind(id).first();
}
async function handleOwnerKnowledge(req,env){
  if(!auth(req,env))return json({ok:false,error:"Unauthorized"},401);
  const u=new URL(req.url);
  try{
    if(u.pathname==="/api/owner-knowledge/import"&&req.method==="POST"){
      const body=await ownerImportReadBody(req);if(body.error)return json({ok:false,error:body.error},body.status);
      const result=await runOwnerKnowledgeImport(env,body);return json(result.body,result.status);
    }
    if(!(await ownerImportStoreReady(env)))return json({ok:false,error:"Owner knowledge import requires migration G"},503);
    if(u.pathname==="/api/owner-knowledge/imports"&&req.method==="GET"){
      const id=String(u.searchParams.get("id")||"");
      if(id)return json({ok:true,...await ownerImportView(env,id)});
      const r=await env.DB.prepare("SELECT id,market,status,summary_json,created_at FROM owner_knowledge_imports ORDER BY created_at DESC LIMIT 20").all();
      return json({ok:true,imports:(r.results||[]).map(x=>{let s={};try{s=JSON.parse(x.summary_json||"{}")}catch{}return {...x,summary:s};})});
    }
    if(u.pathname==="/api/owner-knowledge/items/review"&&req.method==="POST"){
      const b=await req.json().catch(()=>null);return json({ok:true,item:await reviewOwnerKnowledgeItem(env,b)});
    }
    if(u.pathname==="/api/owner-knowledge/imports/approve-parsed"&&req.method==="POST"){
      // Bounded, resumable bulk approval: at most `batch_size` items (default 20, max 30) per request; the dashboard calls
      // again until `remaining` is 0. Only clean parsed items are eligible: rules, ambiguous/rejected/unparsed, conflicting,
      // price-replacing and previously failed items always stay for individual owner review. Every step is idempotent.
      const b=await req.json().catch(()=>null),id=String(b?.import_id||""),limit=Math.min(30,Math.max(1,Math.floor(Number(b?.batch_size)||20)));
      if(!id||b?.confirm_commercial!==true)return json({ok:false,error:"import_id and explicit commercial confirmation are required"},400);
      const rows=(await env.DB.prepare("SELECT * FROM owner_knowledge_import_items WHERE import_id=? AND parse_status='parsed' AND review_status IN ('pending_review','approved') ORDER BY seq").bind(id).all()).results||[];
      const staleBefore=new Date(Date.now()-120000).toISOString(),held=[],eligible=[],stalled=[];
      for(const item of rows){
        let issues=[];try{issues=JSON.parse(item.issues_json||"[]")}catch{}
        // An item left 'approved' without a result (interrupted mid-apply) is resumed once it is clearly stale.
        if(item.review_status==="approved"){if(!item.applied_at&&!item.result_ref&&String(item.updated_at)<staleBefore)stalled.push(item);continue;}
        if(item.item_type==="rule"||issues.some(i=>/conflict|replaces_active_price|mismatch|ambiguous|priced_elsewhere|apply_failed/.test(i.code)))held.push({id:item.id,reason:"needs_individual_review"});
        else eligible.push(item);
      }
      const batch=[...stalled,...eligible].slice(0,limit),applied=[],failed=[];
      for(const item of batch){
        try{
          if(item.review_status==="approved"){
            const result=await applyOwnerKnowledgeItem(env,item),t=now();
            await env.DB.prepare("UPDATE owner_knowledge_import_items SET review_status=?,result_ref=?,applied_at=?,updated_at=? WHERE id=? AND review_status='approved' AND applied_at IS NULL").bind(result.conflict?"approved":"applied",result.result_ref,result.conflict?null:t,t,item.id).run();
          }else await reviewOwnerKnowledgeItem(env,{id:item.id,action:"approve",expected_version:item.version,confirm_commercial:true});
          applied.push(item.id);
        }catch(error){failed.push({id:item.id,reason:sanitizeOperationalError(error?.message||error)});}
      }
      const remaining=Math.max(0,stalled.length+eligible.length-batch.length);
      return json({ok:true,applied:applied.length,approved:applied.length,failed:failed.length,failures:failed,skipped:held.length,held,remaining,batch_size:limit});
    }
    if(u.pathname==="/api/owner-knowledge/imports/reject-remaining"&&req.method==="POST"){
      // REJECT ALL for ONE import: a direct, deterministic owner action on exact item ids — never natural language, never the
      // knowledge engine. Only items of THIS import still awaiting review (pending_review: parsed, ambiguous, unparsed, malformed)
      // are rejected, each through the same version-checked single-item reject. Applied/rejected items are final; an item caught
      // mid-approval ('approved') is left alone. Bounded per request (default 30, max 50); the dashboard repeats until 0 remain.
      // Idempotent: a repeat finds nothing pending, rejects nothing and writes no audit row.
      const b=await req.json().catch(()=>null),id=String(b?.import_id||""),limit=Math.min(50,Math.max(1,Math.floor(Number(b?.batch_size)||30)));
      if(!id||b?.confirm!==true)return json({ok:false,error:"import_id and explicit confirmation are required"},400);
      if(!(await env.DB.prepare("SELECT id FROM owner_knowledge_imports WHERE id=? LIMIT 1").bind(id).first()))return json({ok:false,error:"Import not found"},404);
      const rows=(await env.DB.prepare("SELECT id,version,review_status FROM owner_knowledge_import_items WHERE import_id=? ORDER BY seq").bind(id).all()).results||[];
      const pending=rows.filter(x=>x.review_status==="pending_review"),batch=pending.slice(0,limit),rejected=[],failed=[];
      for(const item of batch){
        try{const r=await reviewOwnerKnowledgeItem(env,{id:item.id,action:"reject",expected_version:item.version});if(r?.review_status==="rejected")rejected.push(item.id);else failed.push({id:item.id,reason:"not_rejected"});}
        catch(error){failed.push({id:item.id,reason:sanitizeOperationalError(error?.message||error)});}
      }
      const remaining=(await env.DB.prepare("SELECT COUNT(*) AS n FROM owner_knowledge_import_items WHERE import_id=? AND review_status='pending_review'").bind(id).first())?.n||0;
      if(rejected.length)try{await audit(env,"owner_knowledge_import_rejected_remaining","Owner rejected the remaining review items of one knowledge import",{import_id:id,rejected:rejected.length,failed:failed.length,remaining_review:Number(remaining)});}catch{}
      return json({ok:true,import_id:id,rejected:rejected.length,rejected_ids:rejected,already_final:rows.length-pending.length,failed:failed.length,failures:failed,remaining_review:Number(remaining),batch_size:limit});
    }
    return json({ok:false,error:"Not found"},404);
  }catch(error){return json({ok:false,error:sanitizeOperationalError(error?.message||error)},400);}
}
// Text-only owner knowledge arriving through /api/autonomy/command (price lists, catalogs, rules).
function looksLikeOwnerKnowledgeImport(text){
  const lines=String(text||"").split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  if(String(text||"").length>4096)return true;
  // Even ONE canonical price line (valid or not) goes to the deterministic importer — never to the command planner or Teach Knowledge.
  if(lines.some(l=>{const c=ownerCanonicalPriceLine(String(l).normalize("NFKC").trim());return !!c&&c.kind!=="skip";}))return true;
  const priced=lines.filter(l=>{const p=parseOwnerKnowledgeLine(l,"IRAN",{product:"x"});return p.kind==="price_row";}).length;
  return lines.length>=2&&priced>=2;
}
const MAX_WEEKLY_FINAL_VIDEO_BYTES=20*1024*1024;
function finalVideoValidationError(message,details={}){
  const error=Error(sanitizeOperationalError(message));
  const declaredLength=Number.isSafeInteger(details.declared_content_length)
    ? details.declared_content_length
    : String(details.declared_content_length??'')
        .replace(/[^\x20-\x7e]/g,'')
        .slice(0,32)||null;
  error.final_video_validation={
    http_status:Number.isInteger(details.http_status)?details.http_status:null,
    content_type:String(details.content_type||'')
      .replace(/[^a-z0-9!#$&^_.+\-/]/gi,'')
      .slice(0,100),
    declared_content_length:declaredLength,
    actual_blob_size:Number.isSafeInteger(details.actual_blob_size)
      ? details.actual_blob_size
      : null,
    reason:String(details.reason||'')
      .replace(/[^a-z0-9_-]/gi,'')
      .slice(0,80)||null,
    maximum_allowed_bytes:Number.isSafeInteger(details.maximum_allowed_bytes)
      ? details.maximum_allowed_bytes
      : null
  };
  return error;
}
async function hasMp4FtypSignature(blob){
  const bytes=new Uint8Array(await blob.slice(0,12).arrayBuffer());
  if(bytes.length<12)return false;
  const boxSize=(bytes[0]*0x1000000)+(bytes[1]<<16)+(bytes[2]<<8)+bytes[3];
  return boxSize>=8 && boxSize<=blob.size &&
    bytes[4]===0x66 && bytes[5]===0x74 &&
    bytes[6]===0x79 && bytes[7]===0x70;
}
function weeklyVideoVaultTag(weekId){
  return `weekly_video:${String(weekId||'').trim()}`;
}
function validWeeklyVideoVaultRecord(row){
  return !!row &&
    String(row.media_id||'').trim()!=='' &&
    /^[1-9]\d*$/.test(String(row.message_id||'')) &&
    Number.isSafeInteger(Number(row.message_id)) &&
    typeof row.file_id==='string' && row.file_id.trim()!=='' &&
    typeof row.file_unique_id==='string' && row.file_unique_id.trim()!=='' &&
    String(row.media_type||'')==='video' &&
    String(row.source_kind||'')==='vault';
}
async function findWeeklyVideoVaultRecord(env,weekId,shotstackTaskId){
  const rows=await env.DB.prepare(`
    SELECT
      m.id AS media_id,
      m.message_id,
      m.file_id,
      m.file_unique_id,
      m.media_type,
      m.source_kind,
      m.caption,
      v.id AS vault_item_id,
      v.tags
    FROM media_vault_items v
    JOIN telegram_media_sources m
      ON m.id=v.telegram_media_id
    JOIN weekly_video_autopilot w ON w.week_id=? AND w.shotstack_task_id=?
    WHERE ((v.tags=? AND v.source_type='weekly_ai_video' AND v.ai_status='ready')
      OR w.output_media_id=m.id)
      AND (m.chat_id=? OR lower(m.chat_username)=?)
  `).bind(String(weekId),String(shotstackTaskId||''),weeklyVideoVaultTag(weekId),
    videoVaultChatId(env),videoVaultChatId(env).replace(/^@/,'').toLowerCase()).all();
  return (rows.results||[]).find(validWeeklyVideoVaultRecord)||null;
}
async function findVideoVaultRecordByFileUniqueId(env,fileUniqueId){
  const value=String(fileUniqueId||'').trim();
  if(!value)return null;
  const rows=await env.DB.prepare(`
    SELECT
      m.id AS media_id,
      m.message_id,
      m.file_id,
      m.file_unique_id,
      m.media_type,
      m.source_kind,
      m.caption,
      v.id AS vault_item_id,
      v.tags
    FROM telegram_media_sources m
    LEFT JOIN media_vault_items v
      ON v.telegram_media_id=m.id
    WHERE m.file_unique_id=?
      AND m.media_type='video'
      AND m.source_kind='vault'
      AND (m.chat_id=? OR lower(m.chat_username)=?)
    ORDER BY m.created_at ASC
  `).bind(value,videoVaultChatId(env),videoVaultChatId(env).replace(/^@/,'').toLowerCase()).all();
  return (rows.results||[]).find(validWeeklyVideoVaultRecord)||null;
}
function telegramWeeklyUploadError(message,details={}){
  const error=Error(sanitizeOperationalError(message));
  error.telegram_weekly_upload={
    outcome:String(details.outcome||'ambiguous'),
    http_status:Number.isInteger(details.http_status)?details.http_status:null,
    response_category:String(details.response_category||'unknown')
      .replace(/[^a-z0-9_-]/gi,'')
      .slice(0,80)
  };
  return error;
}
async function persistWeeklyVideoVaultRecord(env,weekId,caption,identifiers,shotstackTaskId){
  const tagged=await findWeeklyVideoVaultRecord(env,weekId,shotstackTaskId);
  if(tagged)return {...tagged,reused:true,reuse_reason:'weekly_tag'};

  const byFile=await findVideoVaultRecordByFileUniqueId(
    env,
    identifiers.file_unique_id
  );
  if(byFile?.vault_item_id){
    // Retain the existing tag; link this week durably for restart recovery.
    const linked=await env.DB.prepare(`
      UPDATE weekly_video_autopilot SET output_media_id=?
      WHERE week_id=? AND shotstack_task_id=?
        AND status IN ('telegram_uploading','telegram_upload_ambiguous')
    `).bind(byFile.media_id,weekId,shotstackTaskId).run();
    if(Number(linked?.meta?.changes||0)!==1)throw Error('Weekly vault reuse link was not persisted');
    return {...byFile,reused:true,reuse_reason:'file_unique_id'};
  }

  const t=now();
  if(byFile){
    await env.DB.prepare(
      "INSERT INTO media_vault_items(id,telegram_media_id,content_id,source_type,ai_status,ai_prompt,parent_media_id,tags,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)"
    ).bind(
      uid(),
      byFile.media_id,
      null,
      'weekly_ai_video',
      'ready',
      null,
      null,
      weeklyVideoVaultTag(weekId),
      t,
      t
    ).run();
    const completed=await findWeeklyVideoVaultRecord(env,weekId,shotstackTaskId);
    if(!completed)throw Error('Weekly Telegram vault record was not persisted');
    return {...completed,reused:true,reuse_reason:'file_unique_id'};
  }

  const mediaId=uid();
  const statements=[
    env.DB.prepare(
      "INSERT INTO telegram_media_sources(id,chat_id,chat_username,message_id,file_id,file_unique_id,media_type,caption,source_kind,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)"
    ).bind(
      mediaId,
      identifiers.chat_id,
      '',
      identifiers.message_id,
      identifiers.file_id,
      identifiers.file_unique_id,
      'video',
      String(caption||''),
      'vault',
      t,
      t
    ),
    env.DB.prepare(
      "INSERT INTO media_vault_items(id,telegram_media_id,content_id,source_type,ai_status,ai_prompt,parent_media_id,tags,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)"
    ).bind(
      uid(),
      mediaId,
      null,
      'weekly_ai_video',
      'ready',
      null,
      null,
      weeklyVideoVaultTag(weekId),
      t,
      t
    )
  ];
  const results=await env.DB.batch(statements);
  if(!Array.isArray(results)||results.length!==2||results.some(result=>result?.success!==true)){
    throw Error('Weekly Telegram vault batch persistence failed');
  }
  const completed=await findWeeklyVideoVaultRecord(env,weekId,shotstackTaskId);
  if(!completed)throw Error('Weekly Telegram vault record was not persisted');
  return {...completed,reused:false,reuse_reason:''};
}
async function storeWeeklyVideoInVault(env,videoUrl,weekId,caption,shotstackTaskId){
  await ensureMediaVaultStore(env);

  const existing=await findWeeklyVideoVaultRecord(env,weekId,shotstackTaskId);
  if(existing){
    await auditWeeklyVideoObservationOnce(
      env,
      'weekly_video_telegram_vault_reused',
      'Existing weekly Telegram Video Vault record reused',
      {
        week_id:String(weekId),
        shotstack_task_id:String(shotstackTaskId||''),
        media_id:existing.media_id,
        stage:'telegram_reconciliation',
        dedup_key:`${weekId}:${existing.media_id}`
      }
    );
    return {...existing,reused:true};
  }

  const url=String(videoUrl||'').trim();
  if(!/^https?:\/\//i.test(url)){
    throw Error('Weekly video URL missing or invalid');
  }

  const chat=videoVaultChatId(env);
  if(!chat){
    throw Error('TELEGRAM_VIDEO_VAULT_CHAT_ID missing');
  }

  const response=await fetch(url);

  if(!response.ok){
    throw finalVideoValidationError(
      `Failed to download final video (HTTP ${response.status})`,
      {http_status:response.status}
    );
  }

  const contentType=String(
    response.headers.get('content-type')||''
  ).split(';')[0].trim().toLowerCase()
    .replace(/[^a-z0-9!#$&^_.+\-/]/g,'')
    .slice(0,100);
  const genericContentType=contentType==='application/octet-stream';

  if(contentType && contentType!=='video/mp4' && !genericContentType){
    throw finalVideoValidationError(
      `Final video has incompatible Content-Type: ${contentType}`,
      {http_status:response.status,content_type:contentType}
    );
  }

  const rawContentLength=response.headers.get('content-length');
  let declaredContentLength=null;

  if(rawContentLength!==null){
    const normalizedLength=String(rawContentLength).trim();
    if(!/^\d+$/.test(normalizedLength)){
      throw finalVideoValidationError(
        'Final video has malformed Content-Length',
        {
          http_status:response.status,
          content_type:contentType,
          declared_content_length:normalizedLength
        }
      );
    }
    declaredContentLength=Number(normalizedLength);
    if(!Number.isSafeInteger(declaredContentLength)||declaredContentLength<=0){
      throw finalVideoValidationError(
        declaredContentLength===0
          ? 'Final video Content-Length is zero'
          : 'Final video has invalid Content-Length',
        {
          http_status:response.status,
          content_type:contentType,
          declared_content_length:Number.isSafeInteger(declaredContentLength)
            ? declaredContentLength
            : normalizedLength
        }
      );
    }
    if(declaredContentLength>MAX_WEEKLY_FINAL_VIDEO_BYTES){
      throw finalVideoValidationError(
        'Final video exceeds the maximum allowed size',
        {
          reason:'final_video_too_large',
          maximum_allowed_bytes:MAX_WEEKLY_FINAL_VIDEO_BYTES,
          http_status:response.status,
          content_type:contentType,
          declared_content_length:declaredContentLength
        }
      );
    }
  }

  const videoBlob=await response.blob();

  if(videoBlob.size>MAX_WEEKLY_FINAL_VIDEO_BYTES){
    throw finalVideoValidationError(
      'Final video exceeds the maximum allowed size',
      {
        reason:'final_video_too_large',
        maximum_allowed_bytes:MAX_WEEKLY_FINAL_VIDEO_BYTES,
        http_status:response.status,
        content_type:contentType,
        declared_content_length:declaredContentLength,
        actual_blob_size:videoBlob.size
      }
    );
  }

  if(!videoBlob.size){
    throw finalVideoValidationError(
      'Final video download returned empty file',
      {
        http_status:response.status,
        content_type:contentType,
        declared_content_length:declaredContentLength,
        actual_blob_size:videoBlob.size
      }
    );
  }

  if(declaredContentLength!==null && videoBlob.size!==declaredContentLength){
    throw finalVideoValidationError(
      'Final video size does not match Content-Length',
      {
        http_status:response.status,
        content_type:contentType,
        declared_content_length:declaredContentLength,
        actual_blob_size:videoBlob.size
      }
    );
  }

  if(!(await hasMp4FtypSignature(videoBlob))){
    throw finalVideoValidationError(
      'Final video does not have a valid MP4 ftyp signature',
      {
        http_status:response.status,
        content_type:contentType,
        declared_content_length:declaredContentLength,
        actual_blob_size:videoBlob.size
      }
    );
  }

  const upload=new FormData();

  upload.append(
    'chat_id',
    chat
  );

  upload.append(
    'video',
    videoBlob,
    `hamzehi-weekly-${String(weekId||'').replace(/[^a-zA-Z0-9_-]/g,'-')}.mp4`
  );

  if(caption){
    upload.append(
      'caption',
      String(caption).slice(0,1024)
    );
  }

  let uploadClaim;
  try{
    uploadClaim=await env.DB.prepare(`
      UPDATE weekly_video_autopilot
      SET status=?,
          updated_at=?
      WHERE week_id=?
        AND shotstack_task_id=?
        AND status='compositing'
    `).bind(
      'telegram_uploading',
      now(),
      String(weekId),
      String(shotstackTaskId||'')
    ).run();
  }catch(e){
    const localError=Error(sanitizeOperationalError(e));
    localError.telegram_preupload_state=true;
    throw localError;
  }
  if(Number(uploadClaim?.meta?.changes||0)!==1){
    const localError=Error('Telegram upload state could not be persisted');
    localError.telegram_preupload_state=true;
    throw localError;
  }

  let telegramResponse;
  try{
    telegramResponse=await fetch(
      `https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/sendVideo`,
      {method:'POST',body:upload}
    );
  }catch(e){
    throw telegramWeeklyUploadError(e,{
      outcome:'ambiguous',
      response_category:'network_error'
    });
  }

  let telegramData;
  try{
    telegramData=await telegramResponse.json();
  }catch{
    throw telegramWeeklyUploadError('Telegram response could not be read or parsed',{
      outcome:'ambiguous',
      http_status:telegramResponse.status,
      response_category:'unreadable_response'
    });
  }

  const rejected=telegramData?.ok===false &&
    Number.isInteger(telegramData?.error_code) && telegramData.error_code>=400;
  if(!telegramResponse.ok||telegramData?.ok!==true){
    throw telegramWeeklyUploadError(
      telegramData?.description||'Telegram rejected weekly video upload',
      {
        outcome:rejected?'rejected':'ambiguous',
        http_status:telegramResponse.status,
        response_category:rejected?'provider_rejection':'uncertain_response'
      }
    );
  }

  const message=telegramData.result;
  const video=message?.video;
  const identifiers={
    chat_id:chat,
    message_id:String(message?.message_id??'').trim(),
    file_id:typeof video?.file_id==='string'?video.file_id.trim():'',
    file_unique_id:typeof video?.file_unique_id==='string'?video.file_unique_id.trim():''
  };
  if(
    !Number.isSafeInteger(message?.message_id) || message.message_id<=0 ||
    !identifiers.file_id || !identifiers.file_unique_id
  ){
    throw telegramWeeklyUploadError(
      'Telegram success response did not include required video identifiers',
      {
        outcome:'ambiguous',
        http_status:telegramResponse.status,
        response_category:'missing_success_identifiers'
      }
    );
  }

  let stored;
  let persistenceError;
  for(let attempt=0;attempt<2&&!stored;attempt++){
    try{
      stored=await persistWeeklyVideoVaultRecord(
        env,
        weekId,
        caption,
        identifiers,
        shotstackTaskId
      );
    }catch(e){
      persistenceError=e;
    }
  }
  if(!stored){
    throw telegramWeeklyUploadError(persistenceError,{
      outcome:'ambiguous',
      http_status:telegramResponse.status,
      response_category:'local_persistence_failure'
    });
  }
  if(stored.reused){
    await auditWeeklyVideoObservationOnce(env,
      'weekly_video_telegram_vault_reused',
      'Existing Telegram Video Vault identifiers reused during persistence',
      {
        week_id:String(weekId),
        shotstack_task_id:String(shotstackTaskId||''),
        media_id:stored.media_id,
        stage:'telegram_reconciliation',
        reuse_reason:stored.reuse_reason,
        dedup_key:`${weekId}:${stored.media_id}`
      }
    );
  }
  return {ok:true,...stored};
}
async function getMediaVault(env,req){
  if(req.method!=='GET')return json({ok:false,error:'Method not allowed'},405);if(!auth(req,env))return json({ok:false,error:'Unauthorized'},401);await ensureMediaVaultStore(env);const u=new URL(req.url);const limit=Math.min(50,Math.max(1,Number(u.searchParams.get('limit')||24)));const r=await env.DB.prepare("SELECT m.*,v.content_id,v.source_type,v.ai_status,v.ai_prompt,v.parent_media_id,v.tags FROM telegram_media_sources m LEFT JOIN media_vault_items v ON v.telegram_media_id=m.id WHERE m.source_kind='vault' ORDER BY m.created_at DESC LIMIT ?").bind(limit).all();return json({ok:true,items:r.results||[],vault_configured:!!vaultChatId(env)});
}
function detectSupportedImageMime(bytes){
  if(bytes.length>=3&&bytes[0]===0xff&&bytes[1]===0xd8&&bytes[2]===0xff)return 'image/jpeg';
  if(bytes.length>=8&&bytes[0]===0x89&&bytes[1]===0x50&&bytes[2]===0x4e&&bytes[3]===0x47&&bytes[4]===0x0d&&bytes[5]===0x0a&&bytes[6]===0x1a&&bytes[7]===0x0a)return 'image/png';
  if(bytes.length>=12&&bytes[0]===0x52&&bytes[1]===0x49&&bytes[2]===0x46&&bytes[3]===0x46&&bytes[8]===0x57&&bytes[9]===0x45&&bytes[10]===0x42&&bytes[11]===0x50)return 'image/webp';
  return '';
}
async function aiEditVaultImageCore(env, sourceId, prompt, meta = {}){
  await ensureMediaVaultStore(env);
  if(!env.OPENAI_API_KEY) throw Error('OPENAI_API_KEY missing');
  const normalizedSourceId=String(sourceId||'').trim();
  if(!normalizedSourceId) throw Error('Vault photo source ID missing or invalid');
  const src=await env.DB.prepare("SELECT * FROM telegram_media_sources WHERE id=? AND source_kind='vault' AND media_type='photo'").bind(normalizedSourceId).first();
  if(!src) throw Error('Vault photo not found');
  const sourceFileId=String(src.file_id||'').trim();
  if(!sourceFileId) throw Error('Vault photo file ID missing or invalid');
  const fr=await fetch(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/getFile?file_id=${encodeURIComponent(sourceFileId)}`);
  const fd=await fr.json().catch(()=>({}));
  const sourcePath=String(fd.result?.file_path||'').trim();
  if(!fr.ok||!fd.ok||!sourcePath) throw Error('Telegram source image lookup failed');
  const img=await fetch(`https://api.telegram.org/file/bot${env.TELEGRAM_BOT_TOKEN}/${sourcePath}`);
if(!img.ok) throw Error('Telegram source image download failed');

const rawBlob=await img.blob();
 if(!rawBlob.size) throw Error('Telegram source image download returned empty file');
let contentType=String(
  img.headers.get('content-type')||rawBlob.type||''
).split(';')[0].trim().toLowerCase();

 const rawBytes=new Uint8Array(await rawBlob.arrayBuffer());
 if(!contentType||contentType==='application/octet-stream'||contentType==='binary/octet-stream'||contentType==='application/binary'){
   contentType=detectSupportedImageMime(rawBytes);
}

if(!/^image\/(jpeg|png|webp)$/.test(contentType)){
  throw Error(`Unsupported Telegram image MIME type: ${contentType||'unknown'}`);
}
 const filename=contentType==='image/png'?'source.png':contentType==='image/webp'?'source.webp':'source.jpg';
const blob=new Blob(
  [rawBytes],
  {type:contentType}
);

const form=new FormData();
form.append('model',String(env.OPENAI_IMAGE_MODEL||'gpt-image-2'));
form.append('prompt',prompt);
form.append('image',blob,filename);
  form.append('size',String(env.OPENAI_IMAGE_SIZE||'1024x1024'));
  await assertPhotoAutopilotReservation(
    env,
    String(meta.photo_lock_date||''),
    String(meta.photo_lock_created_at||'')
  );
  const r=await fetch('https://api.openai.com/v1/images/edits',{method:'POST',headers:{Authorization:`Bearer ${env.OPENAI_API_KEY}`},body:form});
  const d=await r.json().catch(()=>({}));
  if(!r.ok) throw Error(d?.error?.message||`OpenAI image edit failed (HTTP ${r.status})`);
  const item=d?.data?.[0];
  let outBlob=null;
  if(item?.b64_json){
    const bin=atob(item.b64_json); const bytes=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i); outBlob=new Blob([bytes],{type:'image/png'});
  } else if(item?.url){ const ur=await fetch(item.url); if(ur.ok) outBlob=await ur.blob(); }
  if(!outBlob) throw Error('AI did not return an image');
  const captionImageBase64=await outBlob.arrayBuffer().then(buf=>{
  const bytes=new Uint8Array(buf);
  let binary="";
  const chunkSize=0x8000;

  for(let i=0;i<bytes.length;i+=chunkSize){
    binary+=String.fromCharCode(...bytes.subarray(i,i+chunkSize));
  }

  return `data:${outBlob.type||"image/png"};base64,${btoa(binary)}`;
});
  let finalCaption=String(meta.caption||"").trim();

try{
  await assertPhotoAutopilotReservation(
    env,
    String(meta.photo_lock_date||''),
    String(meta.photo_lock_created_at||'')
  );
  const captionPrompt=
    "Write one original luxury advertising caption for this exact final product image. " +
    "Write entirely in Persian (Farsi). " +
    "Describe only what is actually visible or explicitly verified. " +
    "Use the advertising scene and verified product information as context. " +
    "Include useful product information, a natural call to action, and relevant hashtags. " +
    "Do not invent price, dimensions, materials, features or specifications. " +
    "Do not mention AI, editing, image generation, source IDs, parent IDs, cycles or internal systems. " +
    "Keep the caption elegant, premium, informative and suitable for Telegram. " +
    `Advertising scene: ${String(meta.scene||"")}. ` +
    `Verified product information: ${String(meta.source_caption||"No verified product information available.")}. ` +
    "Return only the final Persian caption.";

  const cr=await fetch(
    "https://api.openai.com/v1/responses",
    {
      method:"POST",
      headers:{
        Authorization:`Bearer ${env.OPENAI_API_KEY}`,
        "Content-Type":"application/json"
      },
      body:JSON.stringify({
        model:String(env.OPENAI_MODEL||"gpt-5.6-luna"),
        input:[
          {
            role:"user",
            content:[
              {
                type:"input_text",
                text:captionPrompt
              },
              {
                type:"input_image",
                image_url:captionImageBase64
              }
            ]
          }
        ]
      })
    }
  );

  const cd=await cr.json().catch(()=>({}));

  if(!cr.ok){
    throw Error(
      cd?.error?.message||
      `Caption generation failed (HTTP ${cr.status})`
    );
  }

  finalCaption=responseText(cd).trim();

  if(!finalCaption){
    throw Error("Caption generation returned empty text");
  }
}catch(e){
  throw Error(`Photo caption generation failed: ${e.message||e}`);
}

meta.caption=finalCaption;
  await assertPhotoAutopilotReservation(
    env,
    String(meta.photo_lock_date||''),
    String(meta.photo_lock_created_at||'')
  );
  const chat=vaultChatId(env); if(!chat) throw Error('TELEGRAM_VAULT_CHAT_ID missing');const upload=new FormData();
upload.append('chat_id',chat);
upload.append('photo',outBlob,'ai-edit.png');
upload.append(
  'caption',
  String(meta.caption||`AI EDIT | parent:${sourceId}`).slice(0,1024)
);
  const tr=await fetch(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/sendPhoto`,{method:'POST',body:upload});
  const td=await tr.json().catch(()=>({})); if(!tr.ok||!td.ok) throw Error(td.description||'Failed to store AI image in vault');
  const tm=td.result,photo=tm.photo?.at(-1); if(!photo?.file_id) throw Error('Vault did not return AI file_id');
  const t=now(),id=uid();
  await env.DB.prepare("INSERT INTO telegram_media_sources(id,chat_id,chat_username,message_id,file_id,file_unique_id,media_type,caption,source_kind,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)")
 .bind(id,chat,'',String(tm.message_id||''),String(photo.file_id),String(photo.file_unique_id||''),'photo',String(meta.caption||''),'vault',t,t).run();
  await env.DB.prepare("INSERT INTO media_vault_items(id,telegram_media_id,content_id,source_type,ai_status,ai_prompt,parent_media_id,tags,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)")
    .bind(uid(),id,meta.content_id||null,'ai_edit','ready',prompt,sourceId,String(meta.tags||'').slice(0,500),t,t).run();
  await audit(env,'media_vault_ai_edit','AI image edit created and stored in Telegram vault',{source_media_id:sourceId,media_id:id,content_id:meta.content_id||null});
  return {media_id:id,source_media_id:sourceId,ai_status:'ready'};
}

async function aiEditVaultImage(env,req){
  if(req.method!=='POST')return json({ok:false,error:'Method not allowed'},405);
  if(!auth(req,env))return json({ok:false,error:'Unauthorized'},401);
  const b=await req.json().catch(()=>null); const sourceId=String(b?.media_id||''); const prompt=String(b?.prompt||'').trim();
  if(!sourceId||!prompt)return json({ok:false,error:'media_id and prompt are required'},400);
  try { const result=await aiEditVaultImageCore(env,sourceId,prompt,{content_id:b?.content_id||null,tags:b?.tags||''}); return json({ok:true,...result}); }
  catch(e){ return json({ok:false,error:e.message||'AI edit failed'},500); }
}
async function createShotstackWeeklyEndCardTask(env,videoUrl,weekId,duration){
  const apiKey=String(env.SHOTSTACK_API_KEY||'').trim();

  if(!apiKey){
    throw Error('SHOTSTACK_API_KEY missing');
  }

  const url=String(videoUrl||'').trim();

  if(!/^https?:\/\//i.test(url)){
    throw Error('Weekly Kling video URL missing or invalid');
  }

  const videoDuration=Number(duration);

  if(!Number.isFinite(videoDuration)||videoDuration<=0){
    throw Error('Weekly Kling video duration missing or invalid');
  }

  const endCardDuration=2;
  
  const payload={
    timeline:{
      background:'#000000',
      tracks:[
  {
    clips:[
      {
        asset:{
          type:'video',
          src:url
        },
        start:0,
        length:videoDuration
      }
    ]
  },
  {
    clips:[
      {
        asset:{
          type:'rich-text',
          text:'HAMZEHIBOX',
          font:{
            family:'Montserrat',
            size:64,
            weight:600,
            color:'#FFFFFF'
          },
          align:{
            horizontal:'center',
            vertical:'middle'
          },
          background:{
            color:'#000000',
            opacity:1
          }
        },
        start:videoDuration,
        length:endCardDuration,
        position:'center'
      }
    ]
  }
]
    },
    output:{
      format:'mp4',
      resolution:'1080',
      aspectRatio:'16:9'
    }
  };

  let response;
  try{
    response=await fetch(
      'https://api.shotstack.io/edit/stage/render',
      {
        method:'POST',
        headers:{
          'x-api-key':apiKey,
          'Content-Type':'application/json',
          'Accept':'application/json'
        },
        body:JSON.stringify(payload)
      }
    );
  }catch(e){
    throw shotstackSubmissionError(e,{
      outcome:'ambiguous',
      response_category:'network_error'
    });
  }

  const raw=await response.text();
  let data;
  try{
    data=raw?JSON.parse(raw):{};
  }catch{
    throw shotstackSubmissionError('Shotstack returned malformed JSON',{
      outcome:response.ok?'ambiguous':'rejected',
      http_status:response.status,
      response_category:response.ok?'malformed_success_response':'http_rejection'
    });
  }

  if(!response.ok||data?.success!==true){
    throw shotstackSubmissionError(
      data?.message||
      data?.response?.message||
      `Shotstack render failed (HTTP ${response.status})`,
      {
        outcome:'rejected',
        http_status:response.status,
        response_category:response.ok?'provider_rejection':'http_rejection'
      }
    );
  }

  const renderId=String(
    data?.response?.id||''
  ).trim();

  if(!renderId){
    throw shotstackSubmissionError('Shotstack did not return render id',{
      outcome:'ambiguous',
      http_status:response.status,
      response_category:'accepted_response_without_render_id'
    });
  }

  return {
    ok:true,
    render_id:renderId,
    http_status:response.status,
    week_id:String(weekId),
    duration:videoDuration
  };
}
function shotstackSubmissionError(message,details={}){
  const error=Error(sanitizeOperationalError(message));
  error.shotstack_submission={
    outcome:String(details.outcome||'ambiguous'),
    http_status:Number.isInteger(details.http_status)?details.http_status:null,
    response_category:String(details.response_category||'unknown')
      .replace(/[^a-z0-9_-]/gi,'')
      .slice(0,80),
    render_id:String(details.render_id||'')
  };
  return error;
}

async function persistAcceptedShotstackRender(env,weekId,klingTaskId,renderId){
  let lastError=null;
  for(let attempt=0;attempt<3;attempt++){
    try{
      const updated=await env.DB.prepare(`
        UPDATE weekly_video_autopilot
        SET status=?, shotstack_task_id=?, updated_at=?
        WHERE week_id=? AND task_id=? AND status='shotstack_submitting'
      `).bind(
        'compositing',
        String(renderId),
        now(),
        String(weekId),
        String(klingTaskId)
      ).run();
      if(Number(updated?.meta?.changes||0)===1)return;

      const existing=await env.DB.prepare(`
        SELECT status,shotstack_task_id
        FROM weekly_video_autopilot
        WHERE week_id=? AND task_id=?
        LIMIT 1
      `).bind(String(weekId),String(klingTaskId)).first();
      if(
        String(existing?.status||'')==='compositing' &&
        String(existing?.shotstack_task_id||'')===String(renderId)
      )return;
      lastError=Error('Accepted Shotstack render could not be persisted in the expected weekly state');
    }catch(e){
      lastError=e;
    }
  }
  throw shotstackSubmissionError(lastError||'Accepted Shotstack render persistence failed',{
    outcome:'ambiguous',
    response_category:'render_id_persistence_failed',
    render_id:String(renderId)
  });
}
function weeklyKlingExternalTaskId(weekId){
  return `weekly-video-${String(weekId||'').replace(/[^a-zA-Z0-9_-]/g,'-')}`;
}

function klingSubmissionError(message, details={}){
  const error=Error(sanitizeOperationalError(message));
  error.kling_submission={
    outcome:String(details.outcome||'ambiguous'),
    http_status:Number.isInteger(details.http_status)?details.http_status:null,
    response_category:String(details.response_category||'unknown'),
    external_task_id:String(details.external_task_id||''),
    task_id:String(details.task_id||'')
  };
  return error;
}

async function createKlingWeeklyVideoTask(env,brief,imageUrls){
  const apiKey=String(env.KLING_API_KEY||'').trim();
  if(!apiKey) throw Error('KLING_API_KEY missing');

  if(!brief?.ok) throw Error('Weekly creative brief is invalid');

  const urls=Array.isArray(imageUrls)
    ? imageUrls.filter(Boolean).slice(0,7)
    : [];

  if(!urls.length){
    throw Error('No source images available for Kling');
  }

  const shots=Array.isArray(brief.shots)
    ? brief.shots.slice(0,6)
    : [];

  if(!shots.length){
    throw Error('No weekly shots available');
  }

  const duration=Math.min(
  12,
  shots.length*2
);

  const multiPrompt=shots.map((shot,index)=>({
    index:index+1,
    prompt:[
      String(shot.direction||''),
      String(brief.story||''),
      'Preserve the exact real HAMZEHI BOX product identity from the referenced image.',
      'Preserve proportions, colors, materials and recognizable product details.',
      'Premium luxury commercial cinematography.',
      'Elegant controlled camera movement and refined lighting.',
      'No voice-over, no dialogue, no subtitles.',
      'Use instrumental luxury cinematic music only. No vocals, no speech, no narration, no spoken words, no dialogue.',
      'End-card text is handled separately; do not generate text inside the scene.'
    ].filter(Boolean).join(' '),
    duration:String(
  index===shots.length-1
    ? Math.max(1,duration-(shots.length-1)*2)
    : 2
)
  }));

  const externalTaskId=weeklyKlingExternalTaskId(brief.week_id);
  const payload={
    model_name:'kling-v3-omni',
    multi_shot:true,
    shot_type:'customize',
    prompt:'',
    multi_prompt:multiPrompt,
    image_list:urls.map(image_url=>({image_url})),
    element_list:[],
    video_list:[],
    mode:'pro',
    sound:'on',
    aspect_ratio:'16:9',
    duration:String(duration),
    callback_url:'',
    external_task_id:externalTaskId
  };

  let response;
  try{
    response=await fetch(
      'https://api-singapore.klingai.com/v1/videos/omni-video',
      {
        method:'POST',
        headers:{
          Authorization:`Bearer ${apiKey}`,
          'Content-Type':'application/json'
        },
        body:JSON.stringify(payload)
      }
    );
  }catch(e){
    throw klingSubmissionError(e,{
      outcome:'ambiguous',
      response_category:'network_error',
      external_task_id:externalTaskId
    });
  }

  const responseText=await response.text();
  let data;
  try{
    data=responseText?JSON.parse(responseText):{};
  }catch{
    throw klingSubmissionError('Kling returned malformed JSON',{
      outcome:response.ok?'ambiguous':'rejected',
      http_status:response.status,
      response_category:response.ok?'malformed_success_response':'http_rejection',
      external_task_id:externalTaskId
    });
  }

  if(!response.ok||Number(data?.code||0)!==0){
    throw klingSubmissionError(
      data?.message||
      `Kling API request failed (HTTP ${response.status})`,
      {
        outcome:'rejected',
        http_status:response.status,
        response_category:response.ok?'provider_rejection':'http_rejection',
        external_task_id:externalTaskId
      }
    );
  }

  const taskId=String(data?.data?.task_id||'').trim();

  if(!taskId){
    throw klingSubmissionError('Kling API did not return task_id',{
      outcome:'ambiguous',
      http_status:response.status,
      response_category:'accepted_response_without_task_id',
      external_task_id:externalTaskId
    });
  }

  return {
    ok:true,
    task_id:taskId,
    external_task_id:externalTaskId,
    http_status:response.status,
    model:'kling-v3-omni',
    duration,
    image_count:urls.length
  };
}

async function persistAcceptedKlingTask(env,weekId,taskId){
  let lastError=null;
  for(let attempt=0;attempt<3;attempt++){
    try{
      const updated=await env.DB.prepare(`
        UPDATE weekly_video_autopilot
        SET status=?, task_id=?, updated_at=?
        WHERE week_id=? AND status='kling_submitting'
      `).bind(
        'generating',
        String(taskId),
        now(),
        String(weekId)
      ).run();
      if(updated.meta?.changes===1) return;

      const existing=await env.DB.prepare(`
        SELECT status,task_id
        FROM weekly_video_autopilot
        WHERE week_id=?
      `).bind(String(weekId)).first();
      if(
        String(existing?.status||'')==='generating' &&
        String(existing?.task_id||'')===String(taskId)
      ) return;
      lastError=Error('Accepted Kling task could not be persisted in the expected weekly state');
    }catch(e){
      lastError=e;
    }
  }
  throw klingSubmissionError(lastError||'Accepted Kling task persistence failed',{
    outcome:'ambiguous',
    response_category:'task_id_persistence_failed',
    task_id:String(taskId)
  });
}

async function getKlingWeeklyVideoTask(env,taskId){
  const apiKey=String(env.KLING_API_KEY||'').trim();
  if(!apiKey) throw Error('KLING_API_KEY missing');

  const id=String(taskId||'').trim();
  if(!id) throw Error('Kling task_id missing');

  const response=await fetch(
    `https://api-singapore.klingai.com/v1/videos/omni-video/${encodeURIComponent(id)}`,
    {
      method:'GET',
      headers:{
        Authorization:`Bearer ${apiKey}`
      }
    }
  );

  const data=await response.json().catch(()=>({}));

  if(!response.ok||Number(data?.code||0)!==0){
    throw Error(
      data?.message||
      `Kling task query failed (HTTP ${response.status})`
    );
  }

  const task=data?.data||{};

  return {
    ok:true,
    task_id:id,
    status:String(task?.task_status||''),
    task_status_msg:String(task?.task_status_msg||''),
    video_url:String(
      task?.task_result?.videos?.[0]?.url||
      ''
    ),
    duration:task?.task_result?.videos?.[0]?.duration||null
  };
}
async function generateWeeklyVideoCaption(env,brief){
  if(!env.OPENAI_API_KEY){
    throw Error('OPENAI_API_KEY missing');
  }

  if(!brief?.ok){
    throw Error('Weekly creative brief is invalid');
  }

  const prompt=[
    'Write one short Persian luxury advertising caption for the completed HAMZEHIBOX weekly video.',
    'Use only the verified information contained in the creative brief below.',
    'Do not invent price, dimensions, materials, specifications, features, certifications or claims.',
    'Do not mention AI, Kling or the generation process.',
    'Do not use English except the brand name HAMZEHIBOX.',
    'Keep the tone elegant, premium and suitable for a luxury jewelry packaging brand.',
    'Return only the final Persian caption, with no quotation marks and no explanation.',
    '',
    `Brand: HAMZEHIBOX`,
    `Concept: ${String(brief.concept||'')}`,
    `Story: ${String(brief.story||'')}`,
    `Product context: ${String(brief.product_context||'')}`,
    `Source scenes: ${JSON.stringify(brief.shots||[])}`,
    `Caption brief: ${String(brief.caption_brief||'')}`
  ].join('\n');

  const r=await fetch(
    'https://api.openai.com/v1/responses',
    {
      method:'POST',
      headers:{
        Authorization:`Bearer ${env.OPENAI_API_KEY}`,
        'Content-Type':'application/json'
      },
      body:JSON.stringify({
        model:env.OPENAI_MODEL||'gpt-5.6-luna',
        input:prompt
      }),
      signal:AbortSignal.timeout(15000)
    }
  );

  const data=await r.json().catch(()=>({}));

  if(!r.ok){
    throw Error(
      data?.error?.message||
      `OpenAI caption generation failed (HTTP ${r.status})`
    );
  }

  const caption=responseText(data).trim();

  if(!caption){
    throw Error('OpenAI returned an empty weekly video caption');
  }

  return caption.slice(0,1024);
}
async function getShotstackWeeklyRender(env,renderId){
  const apiKey=String(env.SHOTSTACK_API_KEY||'').trim();

  if(!apiKey){
    throw Error('SHOTSTACK_API_KEY missing');
  }

  const id=String(renderId||'').trim();

  if(!id){
    throw Error('Shotstack render_id missing');
  }

  const response=await fetch(
    `https://api.shotstack.io/edit/stage/render/${encodeURIComponent(id)}`,
    {
      method:'GET',
      headers:{
        'x-api-key':apiKey,
        'Accept':'application/json'
      }
    }
  );

  const data=await response.json().catch(()=>({}));

  if(!response.ok||!data?.success){
    throw Error(
      data?.message||
      data?.response?.error||
      `Shotstack status request failed (HTTP ${response.status})`
    );
  }

  const render=data?.response||{};

  return {
    ok:true,
    render_id:id,
    status:String(render.status||'').toLowerCase(),
    url:String(render.url||''),
    error:String(render.error||'')
  };
}
async function completeWeeklyVideoFromVault(env,row,stored,caption){
  let lastError;
  for(let attempt=0;attempt<2;attempt++){
    try{
      const updated=await env.DB.prepare(`
        UPDATE weekly_video_autopilot
        SET status=?,
            output_media_id=?,
            caption=?,
            updated_at=?
        WHERE week_id=?
          AND shotstack_task_id=?
          AND status IN (
            'compositing',
            'telegram_uploading',
            'telegram_upload_ambiguous'
          )
      `).bind(
        'video_ready',
        stored.media_id,
        String(caption||stored.caption||''),
        now(),
        row.week_id,
        row.shotstack_task_id
      ).run();
      if(Number(updated?.meta?.changes||0)===1)return true;
      const current=await env.DB.prepare(`
        SELECT status,output_media_id
        FROM weekly_video_autopilot
        WHERE week_id=?
          AND shotstack_task_id=?
        LIMIT 1
      `).bind(row.week_id,row.shotstack_task_id).first();
      if(
        String(current?.status)==='video_ready' &&
        String(current?.output_media_id)===String(stored.media_id)
      )return true;
      lastError=Error('Weekly video completion state was not persisted');
    }catch(e){
      lastError=e;
    }
  }
  const error=Error(sanitizeOperationalError(lastError));
  error.telegram_local_persistence=true;
  throw error;
}
async function reconcileWeeklyVideoVaultRecord(env,row,stored){
  await completeWeeklyVideoFromVault(
    env,
    row,
    stored,
    stored.caption||row.caption||''
  );
  await auditWeeklyVideoObservationOnce(
    env,
    'weekly_video_telegram_vault_reused',
    'Existing weekly Telegram Video Vault record reconciled',
    {
      week_id:row.week_id,
      shotstack_task_id:row.shotstack_task_id||null,
      media_id:stored.media_id,
      stage:'telegram_reconciliation',
      dedup_key:`${row.week_id}:${stored.media_id}`
    }
  );
  return {
    ok:true,
    status:'video_ready',
    week_id:row.week_id,
    shotstack_task_id:row.shotstack_task_id||'',
    output_media_id:stored.media_id,
    reconciled:true
  };
}
async function pollWeeklyVideoAutopilot(env){
  await ensureWeeklyVideoAutopilotStore(env);
  const row=await env.DB.prepare(`
    SELECT
      week_id,
      task_id,
      shotstack_task_id,
      status,
      scenario_json,
      caption,
      updated_at
    FROM weekly_video_autopilot
    WHERE (
      status='generating'
      AND task_id IS NOT NULL
      AND task_id!=''
    )
    OR (
      status='compositing'
      AND shotstack_task_id IS NOT NULL
      AND shotstack_task_id!=''
    )
    OR status='shotstack_submitting'
    OR (
      status IN ('telegram_uploading','telegram_upload_ambiguous')
      AND shotstack_task_id IS NOT NULL
      AND shotstack_task_id!=''
    )
    ORDER BY
      CASE WHEN status='telegram_upload_ambiguous' THEN 1 ELSE 0 END,
      updated_at ASC
    LIMIT 1
  `).first();

  if(!row){
    return {
      ok:true,
      skipped:true,
      reason:"no_active_weekly_video"
    };
  }

  try{
    if(String(row.status)==='shotstack_submitting'){
      const updatedAt=Date.parse(String(row.updated_at||''));
      const stale=!Number.isFinite(updatedAt)||
        updatedAt<=Date.now()-UNKNOWN_PUBLISH_AFTER_MS;
      if(!stale){
        return {
          ok:true,
          status:'shotstack_submitting',
          week_id:row.week_id,
          task_id:row.task_id,
          skipped:true,
          reason:'shotstack_submission_in_progress'
        };
      }
      const ambiguousAt=now();
      await env.DB.prepare(`
        UPDATE weekly_video_autopilot
        SET status=?, updated_at=?
        WHERE week_id=? AND task_id=? AND status='shotstack_submitting'
      `).bind(
        'shotstack_submission_ambiguous',
        ambiguousAt,
        row.week_id,
        row.task_id
      ).run();
      await auditWeeklyVideoObservationOnce(
        env,
        'weekly_video_autopilot_shotstack_submission_ambiguous',
        'Stale Shotstack submission outcome is ambiguous; do not retry',
        {
          week_id:row.week_id,
          task_id:row.task_id||null,
          stage:'shotstack_submission',
          response_category:'stale_submitting_without_render_id',
          error:'Shotstack acceptance cannot be confirmed',
          timestamp:ambiguousAt,
          retry_forbidden:true,
          dedup_key:`${row.week_id}:${row.task_id}:stale_shotstack_submission`
        }
      );
      return {
        ok:false,
        status:'shotstack_submission_ambiguous',
        week_id:row.week_id,
        task_id:row.task_id,
        skipped:true,
        reason:'manual_shotstack_reconciliation_required'
      };
    }
    if(['compositing','telegram_uploading','telegram_upload_ambiguous'].includes(String(row.status))){
      await ensureMediaVaultStore(env);
    }
    if(
      String(row.status)==='telegram_uploading' ||
      String(row.status)==='telegram_upload_ambiguous'
    ){
      const stored=await findWeeklyVideoVaultRecord(env,row.week_id,row.shotstack_task_id);
      if(stored){
        return await reconcileWeeklyVideoVaultRecord(env,row,stored);
      }
      if(String(row.status)==='telegram_upload_ambiguous'){
        return {
          ok:false,
          status:'telegram_upload_ambiguous',
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id,
          skipped:true,
          reason:'manual_telegram_reconciliation_required'
        };
      }
      const updatedAt=Date.parse(String(row.updated_at||''));
      const stale=!Number.isFinite(updatedAt)||
        updatedAt<=Date.now()-UNKNOWN_PUBLISH_AFTER_MS;
      if(!stale){
        return {
          ok:true,
          status:'telegram_uploading',
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id,
          skipped:true,
          reason:'telegram_upload_in_progress'
        };
      }
      await env.DB.prepare(`
        UPDATE weekly_video_autopilot
        SET status=?,
            updated_at=?
        WHERE week_id=?
          AND shotstack_task_id=?
          AND status='telegram_uploading'
      `).bind(
        'telegram_upload_ambiguous',
        now(),
        row.week_id,
        row.shotstack_task_id
      ).run();
      await auditWeeklyVideoObservationOnce(
        env,
        'weekly_video_telegram_upload_ambiguous',
        'Stale Telegram upload has no durable vault record',
        {
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id,
          stage:'telegram_upload',
          response_category:'stale_upload_without_durable_record',
          error:'Telegram acceptance cannot be confirmed',
          dedup_key:`${row.week_id}:${row.shotstack_task_id}:stale`
        }
      );
      return {
        ok:false,
        status:'telegram_upload_ambiguous',
        week_id:row.week_id,
        shotstack_task_id:row.shotstack_task_id,
        error:'Telegram acceptance cannot be confirmed'
      };
    }

    if(String(row.status)==='generating'){
      if(String(row.shotstack_task_id||'').trim()){
        const resumed=await env.DB.prepare(`
          UPDATE weekly_video_autopilot
          SET status=?, updated_at=?
          WHERE week_id=? AND task_id=? AND status='generating'
            AND shotstack_task_id=?
        `).bind(
          'compositing',
          now(),
          row.week_id,
          row.task_id,
          row.shotstack_task_id
        ).run();
        if(Number(resumed?.meta?.changes||0)===1){
          return {
            ok:true,
            status:'compositing',
            week_id:row.week_id,
            task_id:row.task_id,
            shotstack_task_id:row.shotstack_task_id,
            reconciled:true
          };
        }
        return {
          ok:false,
          status:'local_error',
          week_id:row.week_id,
          task_id:row.task_id,
          shotstack_task_id:row.shotstack_task_id,
          error:'Existing Shotstack render state could not be reconciled'
        };
      }
      const task=await getKlingWeeklyVideoTask(
        env,
        row.task_id
      );

      const klingStatus=String(
        task.status||''
      ).toLowerCase();

      if(
        klingStatus==='succeed' ||
        klingStatus==='completed'
      ){
        if(!task.video_url){
          throw Error(
            'Kling completed but video_url is missing'
          );
        }

        const videoDuration=Number(task.duration);

        if(
          !Number.isFinite(videoDuration) ||
          videoDuration<=0
        ){
          throw Error(
            'Kling completed but video duration is missing'
          );
        }

        const submittingAt=now();
        const submissionIntent=await env.DB.prepare(`
          UPDATE weekly_video_autopilot
          SET status=?, updated_at=?
          WHERE week_id=?
            AND task_id=?
            AND status='generating'
        `).bind(
          'shotstack_submitting',
          submittingAt,
          row.week_id,
          row.task_id
        ).run();
        if(Number(submissionIntent?.meta?.changes||0)!==1){
          throw Error('Shotstack submission intent could not be persisted');
        }
        await audit(
          env,
          'weekly_video_autopilot_shotstack_submitting',
          'Weekly Video Autopilot is submitting to Shotstack',
          {
            week_id:row.week_id,
            task_id:row.task_id,
            stage:'shotstack_submission',
            timestamp:submittingAt
          }
        );

        let shotstack;
        try{
          shotstack=await createShotstackWeeklyEndCardTask(
            env,
            task.video_url,
            row.week_id,
            videoDuration
          );
        }catch(e){
          const details=e?.shotstack_submission||{};
          const rejected=details.outcome==='rejected';
          const failureStatus=rejected
            ? 'shotstack_rejected'
            : 'shotstack_submission_ambiguous';
          const failureAt=now();
          await env.DB.prepare(`
            UPDATE weekly_video_autopilot
            SET status=?, updated_at=?
            WHERE week_id=? AND task_id=? AND status='shotstack_submitting'
          `).bind(failureStatus,failureAt,row.week_id,row.task_id).run();
          await audit(
            env,
            rejected
              ? 'weekly_video_autopilot_shotstack_rejected'
              : 'weekly_video_autopilot_shotstack_submission_ambiguous',
            rejected
              ? 'Shotstack rejected the weekly render submission'
              : 'Shotstack render submission outcome is ambiguous; do not retry',
            {
              week_id:row.week_id,
              task_id:row.task_id,
              stage:'shotstack_submission',
              http_status:Number.isInteger(details.http_status)?details.http_status:null,
              response_category:String(details.response_category||'unknown'),
              error:sanitizeOperationalError(e),
              timestamp:failureAt,
              retry_forbidden:true
            }
          );
          return {
            ok:false,
            status:failureStatus,
            week_id:row.week_id,
            task_id:row.task_id,
            error:sanitizeOperationalError(e)
          };
        }

        try{
          await persistAcceptedShotstackRender(
            env,
            row.week_id,
            row.task_id,
            shotstack.render_id
          );
        }catch(e){
          const failureAt=now();
          await env.DB.prepare(`
            UPDATE weekly_video_autopilot
            SET status=?, shotstack_task_id=?, updated_at=?
            WHERE week_id=? AND task_id=? AND status='shotstack_submitting'
          `).bind(
            'shotstack_submission_ambiguous',
            String(shotstack.render_id||''),
            failureAt,
            row.week_id,
            row.task_id
          ).run().catch(()=>{});
          await audit(
            env,
            'weekly_video_autopilot_shotstack_submission_ambiguous',
            'Shotstack accepted the render but local render ID persistence is ambiguous; do not retry',
            {
              week_id:row.week_id,
              task_id:row.task_id,
              shotstack_task_id:String(shotstack.render_id||'')||null,
              stage:'shotstack_render_persistence',
              http_status:Number.isInteger(shotstack.http_status)?shotstack.http_status:null,
              response_category:'render_id_persistence_failed',
              error:sanitizeOperationalError(e),
              timestamp:failureAt,
              retry_forbidden:true
            }
          ).catch(()=>{});
          return {
            ok:false,
            status:'shotstack_submission_ambiguous',
            week_id:row.week_id,
            task_id:row.task_id,
            shotstack_task_id:String(shotstack.render_id||''),
            error:sanitizeOperationalError(e)
          };
        }
        await audit(
          env,
          'weekly_video_autopilot_shotstack_accepted',
          'Shotstack accepted the weekly render submission',
          {
            week_id:row.week_id,
            task_id:row.task_id,
            shotstack_task_id:shotstack.render_id,
            stage:'shotstack_submission',
            http_status:Number.isInteger(shotstack.http_status)?shotstack.http_status:null,
            response_category:'accepted_with_render_id',
            timestamp:now()
          }
        );

        return {
          ok:true,
          status:"compositing",
          week_id:row.week_id,
          task_id:row.task_id,
          shotstack_task_id:shotstack.render_id
        };
      }

      if(klingStatus==='failed'){
               const klingError=String(
          task.task_status_msg||"Kling task failed without error message"
        );

        await audit(
          env,
          "weekly_video_autopilot_failed",
          "Weekly Video Autopilot failed at Kling",
          {
            week_id:row.week_id,
            task_id:row.task_id,
            stage:"kling",
            error:klingError
          }
        );
        await env.DB.prepare(`
          UPDATE weekly_video_autopilot
          SET status=?,
              updated_at=?
          WHERE week_id=?
            AND task_id=?
            AND status='generating'
        `).bind(
          "failed",
          now(),
          row.week_id,
          row.task_id
        ).run();

        return {
          ok:false,
          status:"failed",
          week_id:row.week_id,
          task_id:row.task_id
        };
      }

      return {
        ok:true,
        status:"generating",
        week_id:row.week_id,
        task_id:row.task_id,
        kling_status:klingStatus
      };
    }

    if(String(row.status)==='compositing'){
      const existing=await findWeeklyVideoVaultRecord(env,row.week_id,row.shotstack_task_id);
      if(existing){
        return await reconcileWeeklyVideoVaultRecord(env,row,existing);
      }
      const render=
        await getShotstackWeeklyRender(
          env,
          row.shotstack_task_id
        );

      const shotstackStatus=
        String(render.status||'').toLowerCase();

      if(
        shotstackStatus==='done' ||
        shotstackStatus==='completed'
      ){
        if(!render.url){
          throw Error(
            'Shotstack completed but output URL is missing'
          );
        }

        const brief=JSON.parse(
          String(row.scenario_json||'{}')
        );

        const caption=
          await generateWeeklyVideoCaption(
            env,
            brief
          );

        const stored=
          await storeWeeklyVideoInVault(
            env,
            render.url,
            row.week_id,
            caption,
            row.shotstack_task_id
          );
        await completeWeeklyVideoFromVault(env,row,stored,caption);

        return {
          ok:true,
          status:"video_ready",
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id,
          output_media_id:stored.media_id
        };
      }

      if(
        shotstackStatus==='failed' ||
        shotstackStatus==='error'
      ){
                const shotstackError=String(
          render.error||"Shotstack render failed without error message"
        );

        await audit(
          env,
          "weekly_video_autopilot_failed",
          "Weekly Video Autopilot failed at Shotstack",
          {
            week_id:row.week_id,
            shotstack_task_id:row.shotstack_task_id,
            stage:"shotstack",
            error:shotstackError
          }
        );
        await env.DB.prepare(`
          UPDATE weekly_video_autopilot
          SET status=?,
              updated_at=?
          WHERE week_id=?
            AND shotstack_task_id=?
            AND status='compositing'
        `).bind(
          "failed",
          now(),
          row.week_id,
          row.shotstack_task_id
        ).run();

        return {
          ok:false,
          status:"failed",
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id
        };
      }

      return {
        ok:true,
        status:"compositing",
        week_id:row.week_id,
        shotstack_task_id:row.shotstack_task_id,
        shotstack_status:shotstackStatus
      };
    }

    return {
      ok:true,
      skipped:true,
      reason:"unknown_weekly_video_status",
      status:String(row.status||'')
    };

  }catch(e){
    if(e?.final_video_validation && String(row.status)==='compositing'){
      const validation=e.final_video_validation;
      const validationReason=sanitizeOperationalError(e);
      await audit(
        env,
        "weekly_video_autopilot_failed",
        "Weekly Video Autopilot failed final video validation",
        {
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id||null,
          stage:"final_video_validation",
          http_status:validation.http_status,
          content_type:validation.content_type||null,
          declared_content_length:validation.declared_content_length,
          actual_blob_size:validation.actual_blob_size,
          reason:validation.reason||null,
          maximum_allowed_bytes:validation.maximum_allowed_bytes,
          error:validationReason,
          transient:false
        }
      );
      await env.DB.prepare(`
        UPDATE weekly_video_autopilot
        SET status=?,
            updated_at=?
        WHERE week_id=?
          AND shotstack_task_id=?
          AND status='compositing'
      `).bind(
        "failed",
        now(),
        row.week_id,
        row.shotstack_task_id
      ).run();
      return {
        ok:false,
        status:"failed",
        week_id:row.week_id,
        shotstack_task_id:row.shotstack_task_id||'',
        stage:"final_video_validation",
        error:validationReason
      };
    }
    if(e?.telegram_preupload_state && String(row.status)==='compositing'){
      const localError=sanitizeOperationalError(e);
      await auditWeeklyVideoObservationOnce(
        env,
        'weekly_video_telegram_upload_state_error',
        'Telegram upload was blocked before provider call',
        {
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id||null,
          stage:'telegram_upload_state',
          error:localError,
          dedup_key:`${row.week_id}:${row.shotstack_task_id}:${localError}`
        }
      );
      return {
        ok:false,
        status:'local_error',
        week_id:row.week_id,
        shotstack_task_id:row.shotstack_task_id||'',
        error:localError
      };
    }
    if(e?.telegram_weekly_upload && String(row.status)==='compositing'){
      const outcome=e.telegram_weekly_upload;
      const error=sanitizeOperationalError(e);
      const targetStatus=outcome.outcome==='rejected'
        ? 'telegram_rejected'
        : 'telegram_upload_ambiguous';
      try{
        await env.DB.prepare(`
          UPDATE weekly_video_autopilot
          SET status=?,
              updated_at=?
          WHERE week_id=?
            AND shotstack_task_id=?
            AND status='telegram_uploading'
        `).bind(
          targetStatus,
          now(),
          row.week_id,
          row.shotstack_task_id
        ).run();
      }catch{
        // The durable uploading claim still blocks another send; stale recovery
        // can mark it ambiguous when D1 becomes available again.
      }
      await auditWeeklyVideoObservationOnce(
        env,
        outcome.outcome==='rejected'
          ? 'weekly_video_telegram_upload_rejected'
          : 'weekly_video_telegram_upload_ambiguous',
        outcome.outcome==='rejected'
          ? 'Telegram rejected weekly video upload'
          : 'Telegram weekly video upload outcome is ambiguous',
        {
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id||null,
          stage:'telegram_upload',
          http_status:outcome.http_status,
          response_category:outcome.response_category,
          error,
          dedup_key:[
            row.week_id,
            row.shotstack_task_id||'',
            outcome.outcome,
            outcome.response_category,
            error
          ].join(':')
        }
      );
      return {
        ok:false,
        status:targetStatus,
        week_id:row.week_id,
        shotstack_task_id:row.shotstack_task_id||'',
        error
      };
    }
    if(e?.telegram_local_persistence){
      const localError=sanitizeOperationalError(e);
      await auditWeeklyVideoObservationOnce(
        env,
        'weekly_video_telegram_persistence_error',
        'Telegram video is durable but weekly completion needs reconciliation',
        {
          week_id:row.week_id,
          shotstack_task_id:row.shotstack_task_id||null,
          stage:'telegram_persistence',
          error:localError,
          dedup_key:`${row.week_id}:${row.shotstack_task_id}:${localError}`
        }
      );
      return {
        ok:false,
        status:'local_error',
        week_id:row.week_id,
        shotstack_task_id:row.shotstack_task_id||'',
        error:localError
      };
    }
    const provider=String(row.status)==='generating'
      ? 'kling'
      : String(row.status)==='compositing'
        ? 'shotstack'
        : 'unknown';
    await auditWeeklyVideoObservationOnce(
      env,
      "weekly_video_autopilot_poll_error",
      "Weekly Video Autopilot provider poll failed transiently",
      {
        week_id:row.week_id,
        provider,
        stage:`${provider}_poll`,
        task_id:row.task_id||null,
        shotstack_task_id:row.shotstack_task_id||null,
        error:sanitizeOperationalError(e),
        transient:true,
        dedup_key:[
          row.week_id,
          provider,
          row.task_id||'',
          row.shotstack_task_id||'',
          sanitizeOperationalError(e)
        ].join(':')
      }
    );
    return {
      ok:false,
      status:"poll_error",
      week_id:row.week_id,
      task_id:row.task_id||'',
      shotstack_task_id:row.shotstack_task_id||'',
      error:e.message||String(e)
    };
  }
}
