const KNOWLEDGE_MODEL_NAME=new RegExp("(?:برای\\s*)?(?:مدل(?:\\s+(?:جعبه|box))?|model|موديل|الموديل)\\s+(.+?)(?=\\s+(?:"+KNOWLEDGE_NAME_STOPS.source+"|"+KNOWLEDGE_MARKET_PHRASE+")|$)","i");
