    const m=s.match(new RegExp("(?:(?:چاپ|printing|print|branding)(?:\\s*[:：])?\\s+(?!"+stop+")(.+?)|((?:فویل|foil)(?:\\s+(?!"+stop+").+?)?))(?=\\s+"+stop+"|$)","i"));
