    ask_product:repeat?"بس كولي شنو نوع العلبة اللي تريدها؟":"شنو نوع العلبة اللي تريدها؟",
    ask_quantity:repeat?"بس كولي شكد العدد؟":"شكد العدد اللي تحتاجه؟",
