  const priorEvents=eventIds.length?((await env.DB.prepare(`SELECT id,details_json FROM system_events WHERE id IN (${eventIds.map(()=>"?").join(",")})`).bind(...eventIds).all()).results||[]):[];
  timing.brain_context_ms=Date.now()-wave1;
