function extractTelegramContact(text = "") {
  const s = String(text || "");

  const urlMatch = s.match(
    /https?:\/\/(?:www\.)?t\.me\/([A-Za-z0-9_]{4,64})(?:[/?#][^\s"'<>]*)?/i
  );

  if (urlMatch) {
    const username = urlMatch[1];
    return {
      telegram_username: username,
      telegram_url: `https://t.me/${username}`
    };
  }

  const usernameMatch = s.match(
    /(^|[\s(])@([A-Za-z0-9_]{4,64})(?=$|[\s),.;!?])/i
  );

  if (usernameMatch) {
    const username = usernameMatch[2];
    return {
      telegram_username: username,
      telegram_url: `https://t.me/${username}`
    };
  }

  return {
    telegram_username: null,
    telegram_url: null
  };
}
async function discoverGooglePlaces(env, textQuery, languageCode = "fa", limit = 10) {
  if (!env.GOOGLE_PLACES_API_KEY) {
    return {
      ok: false,
      skipped: true,
      error: "GOOGLE_PLACES_API_KEY not configured",
      items: []
    };
  }

  const url = "https://places.googleapis.com/v1/places:searchText";

  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Goog-Api-Key": env.GOOGLE_PLACES_API_KEY,
      "X-Goog-FieldMask": [
        "places.id",
        "places.displayName",
        "places.formattedAddress",
        "places.googleMapsUri",
        "places.websiteUri",
        "places.internationalPhoneNumber",
        "places.nationalPhoneNumber",
        "places.location",
        "places.types",
        "places.businessStatus"
      ].join(",")
    },
    body: JSON.stringify({
      textQuery: textQuery,
      languageCode,
      pageSize: Math.min(Math.max(Number(limit) || 10, 1), 20)
    }),
    signal: AbortSignal.timeout(12000)
  });

  const data = await response.json().catch(() => ({}));

  if (!response.ok || data.error) {
    return {
      ok: false,
      skipped: false,
      status: response.status,
      error: data.error?.message || `Google Places HTTP ${response.status}`,
      items: []
    };
  }

  const items = (data.places || []).map(place => ({
    provider: "google_places",
    place_id: place.id || null,
    name: place.displayName?.text || null,
    address: place.formattedAddress || null,
    maps_url: place.googleMapsUri || null,
    website: place.websiteUri || null,
    phone: place.internationalPhoneNumber || place.nationalPhoneNumber || null,
    types: Array.isArray(place.types) ? place.types : [],
    business_status: place.businessStatus || null,
    lat: place.location?.latitude ?? null,
    lng: place.location?.longitude ?? null
  }));

  return {
    ok: true,
    skipped: false,
    status: response.status,
    items
  };
} 
